    return stripBidiControls(value).replace(
        /(?:[A-Za-z]+[A-Za-z0-9+&/.\-]*|\+\d+(?:[-–]\d+)?|\d+(?:[-–]\d+)?)/g,
        (token) => `${LRI}${token}${PDI}`,
