        value == null ||
        value === '' ||
        !Number.isInteger(number) ||
        number < minimum ||
        number > maximum
    ) {
        fail(
            `policy ${label} must be an integer between ${minimum} and ${maximum}`,
        );
    }
    return number;
}

function numberInRange(value, minimum, maximum, label) {
